USE SCHEMA DEMO_PARALLELS.RAW;

CREATE OR REPLACE TABLE RAW_CONNECT_CTRS (
    ID              INT AUTOINCREMENT,
    CONTACT_ID      VARCHAR,
    AGENT_ID        VARCHAR,
    CHANNEL         VARCHAR,
    QUEUE           VARCHAR,
    INITIATED_AT    TIMESTAMP,
    CONNECTED_AT    TIMESTAMP,
    DISCONNECTED_AT TIMESTAMP,
    BODY            VARCHAR
);

